use std::fs

fn main() {
    let limit: int = 200000
    let mut sieve: Vec<bool> = [true; 200001]
    let mut count: Vec<int> = [0; 200001]
    let mut largest: Vec<int> = [0; 200001]
    let mut i: int = 2
    while i <= limit {
        if sieve[i] {
            let mut j: int = i * i
            while j <= limit {
                sieve[j] = false
                j += i
            }
        }
        i += 1
    }
    let mut c: int = 0
    let mut last: int = 0
    let mut k: int = 0
    while k <= limit {
        if k >= 2 && sieve[k] {
            c += 1
            last = k
        }
        count[k] = c
        largest[k] = last
        k += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if largest[n] == 0 {
            println("0 none")
        } else {
            println("${count[n]} ${largest[n]}")
        }
    }
}

